export async function loadRoutes() {
  const res = await fetch(TERRAIN.routeUrl);
  if (!res.ok) throw new Error('Could not load route.json');
  const data = await res.json();
  return Object.fromEntries(CLIMBS.map(({ route }) => [route, new Route(route, data[route])]));
}

export function campsFor(routes) {
  return CAMP_DEFS.map((d) => {
    const r = routes[d.route], i = r.tags[d.id];
    return { ...d, x: r.pts[i].x, z: r.pts[i].z, routeIndex: Object.keys(routes).indexOf(d.route), pointIndex: i, s: r.cum[i] };
  });
}

/** Fixed-rope sections as [route, startDistance, endDistance] */
export function ropeDefs(routes) {
  const m = routes.main, l = routes.lhotse, n = routes.nuptse;
  return [
    { name: 'Icefall fixed lines', route: m, s0: m.s('ebc') + 240, s1: m.s('icefall_top') + 60, color: 0x2f7bff },
    { name: 'Lhotse Face fixed ropes', route: m, s0: m.s('bergschrund') - 25, s1: m.s('c4') - 30, color: 0xff3030 },
    { name: 'Summit ropes', route: m, s0: m.s('c4') + 30, s1: m.L - 1, color: 0x30c060 },
    { name: 'Lhotse Couloir fixed ropes', route: l, s0: 2, s1: l.L - 1, color: 0xffa020 },
    { name: 'Nuptse approach fixed line', route: n, s0: 2, s1: n.s('nuptse_bergschrund') + 5, color: 0xc46bff },
    { name: 'Nuptse north face fixed ropes', route: n, s0: n.s('nuptse_bergschrund') - 60, s1: n.L - 1, color: 0xc46bff },
  ];
}

/** Human-readable name of the part of the mountain at (x, z). */
export function regionName(routes, camps, x, z, y) {
  const m = routes.main, l = routes.lhotse, n = routes.nuptse;
  for (const c of CLIMBS) {
    const p = routes[c.route].pts.at(-1);
    if (Math.hypot(x - p.x, z - p.z) < 15 && y > c.minElevation) return `Summit of ${c.name}`;
  }
  for (const c of camps) if (Math.hypot(c.x - x, c.z - z) < (c.id === 'ebc' ? 70 : 32)) return c.name;
  const FAR = { d: Infinity, s: 0 };
  const nm = m.nearestWithin(x, z, 260) || FAR, nl = l.nearestWithin(x, z, 210) || FAR, nn = n.nearestWithin(x, z, 210) || FAR;
  if (nn.d < Math.min(nm.d, nl.d) && nn.d < 200 && nn.s > 25) {
    return nn.s < n.s('nuptse_bergschrund') ? 'Western Cwm · Nuptse approach' : nn.s < n.s('nuptse_rib') ? 'Nuptse North Face' : 'Nuptse North Rib';
  }
  if (nl.d < nm.d && nl.d < 200 && nl.s > 25) return nl.s > l.s('lhotse_c4') ? 'Lhotse Couloir' : 'Upper Lhotse Face';
  if (nm.d < 250) {
    const s = nm.s;
    if (s < m.s('icefall_top')) return 'Khumbu Icefall';
    if (s < m.s('bergschrund')) return 'Western Cwm';
    if (s < m.s('yellowband') - 60) return 'Lhotse Face';
    if (s < m.s('geneva') - 40) return 'Yellow Band';
    if (s < m.s('c4') - 40) return 'Geneva Spur';
    if (s < m.s('c4') + 60) return 'South Col';
    if (s < m.s('balcony') - 30) return 'Triangular Face';
    if (s < m.s('southsummit') - 20) return 'Southeast Ridge';
    if (s < m.s('hillary') - 10) return 'Cornice traverse';
    return 'Summit ridge';
  }
  if (y > 7000) return x < -2200 && z > 1000 ? 'Nuptse' : x > 400 ? 'Kangshung Face' : z < 600 ? 'Southwest Face of Everest' : z > 2200 ? 'Lhotse' : 'Lhotse Face';
  return y > 5900 ? 'Western Cwm' : 'Khumbu Glacier';
}
